arguments.command:
cd /tmp/sv-ea86933732b94ef29ed7f478aeffce4a/symbols && \
# Get all dynamic symbols and try to resolve addresses
# Frame #01: pc 0x222098, #02: 0x222234, #03: 0x19bac0, #06: 0x19bc14
aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk '
BEGIN {
  addrs[1] = "0000000000222098"
  addrs[2] = "0000000000222234"
  addrs[3] = "000000000019bac0"
  addrs[4] = "000000000019bc14"
}
{
  addr = $1
  name = $3
  sym_addrs[NR] = addr
  sym_names[NR] = name
  count = NR
}
END {
  for (i = 1; i <= 4; i++) {
    target = addrs[i]
    best = ""
    best_name = ""
    for (j = 1; j <= count; j++) {
      if (sym_addrs[j] <= target && sym_addrs[j] > best) {
        best = sym_addrs[j]
        best_name = sym_names[j]
      }
    }
    printf "0x%s -> %s+0x%x\n", target, best_name, strtonum("0x" target) - strtonum("0x" best)
  }
}'

